function strOrNull(value) {
  if (value === null || value === undefined) return null;
  const v = String(value).trim();
  return v || null;
}

function normalizeDomain(value) {
  const v = strOrNull(value);
  if (!v) return null;

  return v
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .split('/')[0]
    .split(':')[0]
    .trim() || null;
}

function domainFromUrl(value) {
  const v = strOrNull(value);
  if (!v) return null;

  try {
    const m = v.match(/^https?:\/\/([^\/?#]+)/i);
    if (!m) return null;
    return normalizeDomain(m[1]);
  } catch {
    return null;
  }
}

function countryCode(value) {
  const v = strOrNull(value);
  if (!v) return null;

  if (/^[A-Za-z]{2}$/.test(v)) {
    return v.toUpperCase();
  }

  const key = v.toLowerCase();

  const map = {
    malaysia: 'MY',
    singapore: 'SG',
    thailand: 'TH',
    indonesia: 'ID',
    brunei: 'BN',
    'brunei darussalam': 'BN',
    philippines: 'PH',
    'the philippines': 'PH',
    vietnam: 'VN',
    'viet nam': 'VN',
    cambodia: 'KH',
    laos: 'LA',
    'lao pdr': 'LA',
    myanmar: 'MM',
  };

  return map[key] ?? null;
}

function cleanArray(value) {
  if (!Array.isArray(value)) return [];

  const out = [];
  const seen = new Set();

  for (const item of value) {
    const v = strOrNull(item);
    if (!v) continue;

    const key = v.toLowerCase();
    if (seen.has(key)) continue;

    seen.add(key);
    out.push(v);
  }

  return out;
}

const icpProfileId = ICP_PROFILE_IDS[data.suggested_icp];

