function normalizeDomain(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/^www\./, '')
    .replace(/:\d+$/, '');
}

function canonicalizePageUrl(rawUrl) {
  const raw = String(rawUrl ?? '').trim();

  const match = raw.match(
    /^(https?):\/\/([^\/?#]+)([^?#]*)(?:\?([^#]*))?/i
  );

  if (!match) {
    return null;
  }

  const host = normalizeDomain(match[2]);

  let path = match[3] || '/';
  path = path.replace(/\/{2,}/g, '/');

  if (path.length > 1) {
    path = path.replace(/\/+$/, '');
  }

  const query = String(match[4] ?? '');

  const trackingKeys = new Set([
    'gclid',
    'fbclid',
    'msclkid',
    'ref',
    'ref_src',
  ]);

  const kept = [];

  if (query) {
    for (const part of query.split('&')) {
      if (!part) continue;

      const [rawKey] = part.split('=');
      const key = safeDecode(rawKey || '').toLowerCase();

      if (
        key.startsWith('utm_') ||
        trackingKeys.has(key)
      ) {
        continue;
      }

      kept.push(part);
    }
  }

  return {
    host,
    page_url:
      `https://${host}${path}` +
      (kept.length ? `?${kept.join('&')}` : ''),
  };
}

